**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>
#include <vector>
#include <map>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int liczba;
    vector<int> liczby;
    vector<int> roznice;

    cout << "a) Operacja Kaprekara:" << endl;
    while (plik >> liczba) {
        liczby.push_back(liczba);
        string s = to_string(liczba);
        string sA = s, sD = s;
        sort(sA.begin(), sA.end());
        sort(sD.begin(), sD.end(), greater<char>());
        int A = stoi(sA);
        int D = stoi(sD);
        int diff = D - A;
        roznice.push_back(diff);
        cout << liczba << ": D=" << D << ", A=" << A
             << ", D-A=" << diff << endl;
    }

    cout << endl << "b) Liczb osiagajacych 6174 w jednym kroku: ";
    int ile6174 = 0;
    for (int r : roznice) {
        if (r == 6174) ile6174++;
    }
    cout << ile6174 << endl;

    cout << endl << "c) Najczestsza roznica: ";
    map<int, int> freq;
    for (int r : roznice) freq[r]++;
    int maxR = roznice[0], maxCnt = 0;
    for (auto& p : freq) {
        if (p.second > maxCnt) {
            maxCnt = p.second;
            maxR = p.first;
        }
    }
    cout << maxR << " (" << maxCnt << " razy)" << endl;
    return 0;
}
```

**Wyjasnienie**: Operacja Kaprekara wymaga posortowania cyfr. Uzycie `string` + `sort` to najprostsza metoda. `greater<char>()` daje kolejnosc malejaca. `map` zlicza czestotliwosci roznic.

